import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, of, tap } from 'rxjs';
import { SessionService } from './session.service';
import { SheetService } from './sheet.service';

export type Grade = 'A' | 'B' | 'C';

export const GRADES: readonly Grade[] = ['A', 'B', 'C'];

export interface Person {
  id: number;
  name: string;
  grade: Grade;
}

export interface PersonForm {
  name: string;
  grade: Grade;
}

// The active sheet's people, in the order they were added.
@Injectable({ providedIn: 'root' })
export class PeopleService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly list = signal<Person[]>([]);

  readonly people = this.list.asReadonly();

  /** Re-read the active sheet's people from the store. */
  reload(): Observable<unknown> {
    const id = this.sheets.sheetId();
    if (!id) {
      this.list.set([]);
      return of(null);
    }
    return this.http
      .get<Person[]>(this.url(id), { headers: this.session.headers() })
      .pipe(tap((people) => {
        if (this.sheets.sheetId() === id) this.list.set(people);
      }));
  }

  add(form: PersonForm): Observable<Person> {
    return this.http
      .post<Person>(this.url(this.sheet()), form, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => [...all, p])));
  }

  edit(personId: number, form: PersonForm): Observable<Person> {
    return this.http
      .put<Person>(`${this.url(this.sheet())}/${personId}`, form, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => all.map((o) => (o.id === p.id ? p : o)))));
  }

  private sheet(): string {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return id;
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/people`;
  }
}
import { Component, computed, effect, inject, signal, untracked } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { GRADES, Grade, PeopleService, Person } from '../../core/people.service';
import { SheetService } from '../../core/sheet.service';
import { ClaimsService, claimDue, counts, money } from '../../core/claims.service';
import { RatesService } from '../../core/rates.service';
import { PersonClaims } from './person-claims';

// The sheet's people: a form that adds a person or edits the one opened, and the list with each
// person's claims, claimed and due-total, and the sheet's claimed total and due-total. A due-total
// is the sum of the person's open and settled claims' (already rounded) dues, 0.00 with none; a
// person whose grade has no rate in force on the sheet's today has no due-total (n/a) unless a
// settled claim of theirs keeps a fixed due. The sheet's due-total skips those with none.
@Component({
  selector: 'app-people',
  imports: [ReactiveFormsModule, PersonClaims],
  template: `
    <section aria-labelledby="people-heading">
      <h2 id="people-heading">People</h2>
      <form [formGroup]="form" (ngSubmit)="submit()" [attr.aria-label]="editing() === null ? 'Add person' : 'Edit person'">
        <label for="person-form-name">Name</label>
        <input id="person-form-name" data-testid="person-form-name" formControlName="name" />
        <label for="person-form-grade">Grade</label>
        <select id="person-form-grade" data-testid="person-form-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <button type="submit" data-testid="person-form-submit">{{ editing() === null ? 'Add' : 'Save' }}</button>
        @if (editing() !== null) {
          <button type="button" data-testid="person-form-cancel" (click)="reset()">Cancel</button>
        }
        @if (error()) {
          <p role="alert" data-testid="person-form-error">{{ error() }}</p>
        }
      </form>
      <table>
        <thead>
          <tr>
            <th scope="col">Name</th><th scope="col">Grade</th><th scope="col">Claimed</th><th scope="col">Due</th>
            <th scope="col"><span class="visually-hidden">Actions</span></th><th scope="col">Claims</th>
          </tr>
        </thead>
        <tbody>
          @for (p of people.people(); track p.id) {
            <tr [attr.data-testid]="'person-row-' + p.id">
              <td data-testid="person-name">{{ p.name }}</td>
              <td data-testid="person-grade">{{ p.grade }}</td>
              <td data-testid="person-claimed">{{ money(claims.claimedCents().get(p.id) ?? 0) }}</td>
              <td data-testid="person-due-total">{{ amountOrNa(dueTotals().get(p.id)) }}</td>
              <td>
                <button type="button" [attr.data-testid]="'person-edit-' + p.id" (click)="open(p)"
                  [attr.aria-label]="'Edit ' + p.name">Edit</button>
              </td>
              <td><app-person-claims [personId]="p.id" [personName]="p.name" [grade]="p.grade" /></td>
            </tr>
          }
        </tbody>
      </table>
      <p>Claimed in total: <span data-testid="rollup-claimed-total">{{ money(claims.totalCents()) }}</span></p>
      <p>Due in total: <span data-testid="rollup-due-total">{{ money(dueTotal()) }}</span></p>
    </section>
  `,
})
export class People {
  protected readonly people = inject(PeopleService);
  protected readonly claims = inject(ClaimsService);
  private readonly rates = inject(RatesService);
  private readonly sheets = inject(SheetService);
  protected readonly money = money;
  protected readonly grades = GRADES;
  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
    grade: new FormControl<Grade>('A', { nonNullable: true }),
  });
  protected readonly editing = signal<number | null>(null);
  protected readonly error = signal('');
  /**
   * Each person's due-total in cents: the sum of their open and settled claims' dues (those with one);
   * absent when their grade has no rate in force today and no settled claim of theirs keeps a due.
   */
  protected readonly dueTotals = computed(() => {
    const out = new Map<number, number>();
    for (const p of this.people.people()) {
      const counted = (this.claims.byPerson().get(p.id) ?? []).filter(counts);
      if (!this.rates.byGrade().has(p.grade) && !counted.some((c) => c.due !== null)) continue;
      const rateOn = (date: string) => this.rates.rateOn(p.grade, date);
      out.set(p.id, counted.reduce((sum, c) => sum + (claimDue(c, rateOn) ?? 0), 0));
    }
    return out;
  });
  /** Everyone's due-total added up, in cents, skipping those with none. */
  protected readonly dueTotal = computed(() => [...this.dueTotals().values()].reduce((sum, d) => sum + d, 0));

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    effect(() => {
      this.sheets.loads();
      untracked(() => {
        this.reset();
      });
    });
  }

  protected amountOrNa(cents: number | undefined): string {
    return cents === undefined ? 'n/a' : money(cents);
  }

  protected open(p: Person): void {
    this.error.set('');
    this.editing.set(p.id);
    this.form.setValue({ name: p.name, grade: p.grade }, { emitEvent: false });
  }

  protected reset(): void {
    this.error.set('');
    this.editing.set(null);
    this.form.reset({ name: '', grade: 'A' }, { emitEvent: false });
  }

  protected submit(): void {
    this.error.set('');
    const { name, grade } = this.form.getRawValue();
    if (!name.trim()) {
      this.error.set('Enter a name.');
      return;
    }
    const id = this.editing();
    const saved = id === null ? this.people.add({ name, grade }) : this.people.edit(id, { name, grade });
    saved.subscribe({
      next: () => this.reset(),
      error: (e: { status?: number }) =>
        this.error.set(
          e.status === 409
            ? 'That name is already in use.'
            : id === null ? 'Could not add that person.' : 'Could not save that person.',
        ),
    });
  }
}
import { Component, computed, inject, input, signal } from '@angular/core';
import { HttpErrorResponse } from '@angular/common/http';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Claim, ClaimAction, ClaimsService, claimDue, money } from '../../core/claims.service';
import { Grade } from '../../core/people.service';
import { RatesService } from '../../core/rates.service';

// A person's claims, newest first, each with its status and buttons to open, settle or void it, who opened it (they may not settle it), its due (n/a when the person's grade has no rate in force on the claim's date), and a form that adds a claim or edits the one opened.
@Component({
  selector: 'app-person-claims',
  imports: [ReactiveFormsModule],
  template: `
    <ul [attr.aria-label]="'Claims of ' + personName()">
      @for (c of claims(); track c.id) {
        <li [attr.data-testid]="'claim-row-' + c.id">
          <span data-testid="claim-amount">{{ c.amount }}</span>
          <span data-testid="claim-date">{{ c.date }}</span>
          <span data-testid="claim-note">{{ c.note }}</span>
          <span>Due <span data-testid="claim-due">{{ dueOf(c) }}</span></span>
          <span>No. <span data-testid="claim-number">{{ c.number ?? '' }}</span></span>
          <span>Status <span data-testid="claim-status">{{ c.status }}</span></span>
          <span>Opened by <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span></span>
          <button type="button" data-testid="claim-edit" (click)="open(c)"
            [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date">Edit</button>
          @for (a of actions; track a.action) {
            <button type="button" [attr.data-testid]="'claim-' + a.action" (click)="change(c, a.action)"
              [attr.aria-label]="a.label + ' claim of ' + c.amount + ' on ' + c.date">{{ a.label }}</button>
          }
          @if (claimErrors().get(c.id); as e) {
            <p role="alert" data-testid="claim-error">{{ e }}</p>
          }
        </li>
      }
    </ul>
    <form [formGroup]="form" (ngSubmit)="submit()"
      [attr.aria-label]="(editing() === null ? 'Add claim for ' : 'Edit claim of ') + personName()">
      <label [for]="'claim-form-amount-' + personId()">Amount</label>
      <input [id]="'claim-form-amount-' + personId()" data-testid="claim-form-amount" formControlName="amount"
        inputmode="decimal" />
      <label [for]="'claim-form-date-' + personId()">Date (empty: today)</label>
      <input [id]="'claim-form-date-' + personId()" type="date" data-testid="claim-form-date" formControlName="date" />
      <label [for]="'claim-form-note-' + personId()">Note</label>
      <input [id]="'claim-form-note-' + personId()" data-testid="claim-form-note" formControlName="note" />
      <button type="submit" data-testid="claim-form-submit">{{ editing() === null ? 'Add claim' : 'Save claim' }}</button>
      @if (editing() !== null) {
        <button type="button" data-testid="claim-form-cancel" (click)="reset()">Cancel</button>
      }
      @if (error()) {
        <p role="alert" data-testid="claim-form-error">{{ error() }}</p>
      }
    </form>
  `,
})
export class PersonClaims {
  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  readonly grade = input.required<Grade>();
  private readonly service = inject(ClaimsService);
  private readonly rates = inject(RatesService);
  protected readonly claims = computed(() => this.service.byPerson().get(this.personId()) ?? []);
